def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.
    """
    try:
        combos = []

        def is_valid(num):
            s = str(num)
            # Must not contain zero and each digit must be unique
            return '0' not in s and len(s) == len(set(s))

        # Use bitmask to track used digits (bits 1-9)
        def dfs(current_num, current_len, max_len, used_mask):
            if current_len == max_len:
                first = current_num
                second = first * 2
                third = first * 3
                if is_valid(second) and is_valid(third):
                    combos.append((first, second, third))
                return
            for digit in range(1, 10):
                bit = 1 << digit
                if not (used_mask & bit):
                    dfs(current_num * 10 + digit, current_len + 1, max_len, used_mask | bit)

        # Generate numbers of length 1 to 9
        for length in range(1, 10):
            dfs(0, 0, length, 0)

        # Sort the result based on the first number
        combos.sort(key=lambda x: x[0])
        return combos
    except Exception:
        # In case of any unexpected error, return an empty list
        return []

def max_happiness(n: int, m: int, items: list) -> int:
    """
    Calculate the maximum total importance value achievable within a given budget.

    Args:
        n (int): Total budget available for purchasing items.
        m (int): Number of items available for selection.
        items (list of tuple[int, int]): Each tuple contains (price, importance).

    Returns:
        int: Maximum total importance value within the budget.
    """
    # Basic input validation
    try:
        if not isinstance(n, int) or not isinstance(m, int):
            return 0
        if n < 0 or m < 0:
            return 0
        if not isinstance(items, list):
            return 0
        if len(items) != m:
            return 0
        for price, importance in items:
            if not isinstance(price, int) or not isinstance(importance, int):
                raise ValueError
            if price < 0 or importance < 0:
                raise ValueError
    except Exception:
        return 0

    # Dynamic programming for 0-1 knapsack
    dp = [0] * (n + 1)
    for price, importance in items:
        value = price * importance
        for w in range(n, price - 1, -1):
            new_val = dp[w - price] + value
            if new_val > dp[w]:
                dp[w] = new_val
    return dp[n]

def decode(encoded: str, original: str, message: str) -> str:
    """Decode an encrypted message using a substitution cipher derived from a known
    encoded-original pair. Return "Failed" if a contradiction occurs or the cipher
    does not cover all 26 uppercase letters."""
    # Check lengths match
    if len(encoded) != len(original):
        return "Failed"
    # Build mapping
    mapping: dict[str, str] = {}
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"  # contradictory mapping
        else:
            mapping[e_char] = o_char
    # Ensure mapping covers all 26 uppercase letters
    if len(mapping) != 26:
        return "Failed"
    # Decode message
    decoded = []
    for char in message:
        if char not in mapping:
            return "Failed"  # message contains unknown character
        decoded.append(mapping[char])
    return "".join(decoded)

def min_remaining_space(V: int, n: int, volumes: list) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.
    """
    # Basic validation
    try:
        if not isinstance(V, int) or V < 0:
            raise ValueError("V must be a non‑negative integer")
        if not isinstance(n, int) or n < 0:
            raise ValueError("n must be a non‑negative integer")
        if volumes is None:
            raise ValueError("volumes cannot be None")
        if not isinstance(volumes, list):
            raise ValueError("volumes must be a list")
    except Exception as e:
        raise e

    # Use only the first n items as specified
    sizes = volumes[:n]

    # Initialise DP array for reachable volumes
    reachable = [False] * (V + 1)
    reachable[0] = True

    # 0/1 knapsack DP
    for size in sizes:
        if not isinstance(size, int) or size < 0:
            # Skip invalid item sizes
            continue
        if size > V:
            continue
        for cap in range(V, size - 1, -1):
            if reachable[cap - size]:
                reachable[cap] = True

    # Find the maximum volume that can be occupied
    max_occupied = max((i for i, ok in enumerate(reachable) if ok), default=0)

    return V - max_occupied

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.

    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Basic validation
    if not isinstance(heights, (list, tuple)):
        raise TypeError("heights must be a list or tuple of integers")
    for idx, h in enumerate(heights):
        if not isinstance(h, int):
            raise TypeError(f"Element at index {idx} is not an integer")

    n = len(heights)
    if n <= 1:
        return 0  # Already a valid formation

