    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # Find maximum bitonic subsequence length
    best = 0
    for i in range(n):
        bitonic_len = inc[i] + dec[i] - 1  # peak counted twice
        if bitonic_len > best:
            best = bitonic_len

    return n - best""
